  "verdict": "pended",
  "governing_rule": "MP-ONC-001",
  "reason": "The diagnosis of diffuse large B-cell lymphoma supports use of rituximab, and the member's eligibility, network status, benefit accumulator, and prior authorization history are all in order. However, the clinical justification submitted is generic template language (referencing physical therapy and conservative treatment) and does not document the required treatment regimen, planned dose/schedule, cycle number, or baseline hepatitis B screening results required under medical policy MP-ONC-001 before rituximab can be authorized.",
  "missing_information": [
    "Specific treatment regimen/protocol (e.g., R-CHOP) with planned dose and schedule",
    "Cycle number for this rituximab administration",
    "Documentation of hepatitis B surface antigen and core antibody screening results prior to initiation"
  ]
}
